package main
import "fmt"
var calls int
func pair(a,b int64)(int64,int64){calls++;return a+b,a-b}
func main(){
 values:=[]int64{-9223372036854775808,-9223372036854775807,-17,-1,0,1,17,9223372036854775806,9223372036854775807}
 checked:=0
 for _,r0:=range values{for _,r1:=range values{
  calls=0
  v:=func(r0 int64,r1 int64)struct{result0 int64;result1 int64}{return struct{result0 int64;result1 int64}{r0,r1}}(pair(r0,r1))
  if calls!=1||v.result0!=int64(uint64(r0)+uint64(r1))||v.result1!=int64(uint64(r0)-uint64(r1)){panic("call adapter")}
  calls=0
  a,b:=func(v struct{result0 int64;result1 int64})(int64,int64){return v.result0,v.result1}(func(r0 int64,r1 int64)struct{result0 int64;result1 int64}{return struct{result0 int64;result1 int64}{r0,r1}}(pair(r0,r1)))
  if calls!=1||a!=v.result0||b!=v.result1{panic("return adapter")}
  checked++
 }}
 fmt.Println(checked)
}
